\section*{Nesterov's Accelerated Gradient Descent}

\section*{Mathematical Formulation}
Let $f: \mathbb{R}^n \to \mathbb{R}$ be an objective function. Nesterov's Accelerated Gradient Descent maintains two sequences $\{x_k\}$ and $\{y_k\}$, updated as follows:
\begin{align}
    y_k &= x_k + \beta_k(x_k - x_{k-1}) \\
    x_{k+1} &= y_k - \alpha \nabla f(y_k)
\end{align}
where $\alpha > 0$ is the step size, and $\beta_k$ is the momentum parameter. For a $\mu$-strongly convex and $L$-smooth function, the optimal momentum schedule is given by:
\begin{align}
    \beta_k = \frac{\sqrt{L} - \sqrt{\mu}}{\sqrt{L} + \sqrt{\mu}} = \frac{\sqrt{\kappa} - 1}{\sqrt{\kappa} + 1}
\end{align}
where $\kappa = L/\mu$ is the condition number.

\section*{Pseudocode}
\begin{algorithmic}[1]
\State \textbf{Input:} Initial point $x_0 \in \mathbb{R}^n$, step size $\alpha = 1/L$, condition number $\kappa = L/\mu$
\State Set $x_{-1} \leftarrow x_0$
\State $\beta \leftarrow (\sqrt{\kappa} - 1) / (\sqrt{\kappa} + 1)$
\For{$k = 0, 1, 2, \dots, K-1$}
    \State $y_k \leftarrow x_k + \beta(x_k - x_{k-1})$
    \State $x_{k+1} \leftarrow y_k - \alpha \nabla f(y_k)$
\EndFor
\State \textbf{Output:} $x_K$
\end{algorithmic}

\section*{Dry Run Example}
Let $f(w) = (w-3)^2$. This is a $1$-strongly convex and $1$-smooth function ($\mu=1, L=1, \kappa=1$).
\begin{itemize}
    \item Optimal step size: $\alpha = 1/L = 1$.
    \item Momentum schedule: $\beta = (\sqrt{1}-1)/(\sqrt{1}+1) = 0$.
    \item Gradient: $\nabla f(w) = 2(w-3)$.
    \item Initial point: $x_0 = 0$. We set $x_{-1} = x_0 = 0$.
\end{itemize}
Since $\beta = 0$, the algorithm reduces to standard Gradient Descent.

\textbf{Iteration 1 ($k=0$):}
\begin{align}
    y_0 &= x_0 + 0(x_0 - x_{-1}) = 0 \\
    x_1 &= y_0 - 1 \cdot \nabla f(y_0) = 0 - 2(0-3) = 6 \\
    f(x_1) &= (6-3)^2 = 9
\end{align}

\textbf{Iteration 2 ($k=1$):}
\begin{align}
    y_1 &= x_1 + 0(x_1 - x_0) = 6 \\
    x_2 &= y_1 - 1 \cdot \nabla f(y_1) = 6 - 2(6-3) = 0 \\
    f(x_2) &= (0-3)^2 = 9
\end{align}

\textbf{Iteration 3 ($k=2$):}
\begin{align}
    y_2 &= x_2 + 0(x_2 - x_1) = 0 \\
    x_3 &= y_2 - 1 \cdot \nabla f(y_2) = 0 - 2(0-3) = 6 \\
    f(x_3) &= (6-3)^2 = 9
\end{align}
\textit{Note:} With $\kappa=1$, $\beta=0$ and $\alpha=1$, the iterates oscillate between $0$ and $6$. This occurs because $\alpha=1$ is at the boundary of the step size stability condition $\alpha < 2/L$. For convergence, one could pick $\alpha=0.1$ as requested by the prompt's parameter, yielding:
\begin{align}
    x_1 &= 0 - 0.1(2(0-3)) = 0.6, \quad f(x_1) = 5.76 \\
    x_2 &= 0.6 - 0.1(2(0.6-3)) = 1.08, \quad f(x_2) = 3.6864 \\
    x_3 &= 1.08 - 0.1(2(1.08-3)) = 1.464, \quad f(x_3) = 2.3604
\end{align}

\section*{Assumptions}
\begin{definition}[$\mu$-Strongly Convex]
A differentiable function $f$ is $\mu$-strongly convex ($\mu > 0$) if for all $x, y \in \mathbb{R}^n$:
\begin{align}
    f(y) \geq f(x) + \langle \nabla f(x), y - x \rangle + \frac{\mu}{2}\|y - x\|^2
\end{align}
\end{definition}

\begin{definition}[$L$-Smooth]
A differentiable function $f$ is $L$-smooth ($L > 0$) if for all $x, y \in \mathbb{R}^n$:
\begin{align}
    f(y) \leq f(x) + \langle \nabla f(x), y - x \rangle + \frac{L}{2}\|y - x\|^2
\end{align}
\end{definition}

\section*{Main Convergence Theorem}
\begin{theorem}
Let $f$ be $\mu$-strongly convex and $L$-smooth, with unique minimizer $x^*$. Let the step size $\alpha = 1/L$ and the momentum parameter $\beta = \frac{\sqrt{L}-\sqrt{\mu}}{\sqrt{L}+\sqrt{\mu}}$. Define the Lyapunov function:
\begin{align}
    V_k = f(x_k) - f(x^*) + \frac{\mu}{2}\|z_k - x^*\|^2
\end{align}
where $z_k = x_k + \frac{1-\beta}{\beta}(x_k - x_{k-1})$. Then, for all $k \geq 0$:
\begin{align}
    V_{k+1} \leq \left(\frac{\sqrt{L}-\sqrt{\mu}}{\sqrt{L}+\sqrt{\mu}}\right)^2 V_k
\end{align}
Consequently, $f(x_k) - f(x^*) \leq \left(\frac{\sqrt{L}-\sqrt{\mu}}{\sqrt{L}+\sqrt{\mu}}\right)^{2k} (f(x_0) - f(x^*))$, yielding a linear convergence rate of $O\left(\left(\frac{\sqrt{\kappa}-1}{\sqrt{\kappa}+1}\right)^{2k}\right)$.
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}
    \item \textbf{Optimal Rate:} Nesterov's method achieves the optimal lower bound for first-order methods on strongly convex smooth problems.
    \item \textbf{Stability:} The step size $\alpha=1/L$ is the maximal stable step size, ensuring monotonic decrease of the Lyapunov function.
    \item \textbf{Hyperparameter Sensitivity:} The convergence is highly sensitive to the estimation of $L$ and $\mu$. Overestimating $L$ slows convergence, while underestimating $L$ may cause divergence.
\end{itemize}

\section*{Discussion}
Compared to standard Gradient Descent (GD), which converges at $O((\frac{\kappa-1}{\kappa+1})^{2k})$, Nesterov's acceleration fundamentally improves the dependency on $\kappa$ to $O((\frac{\sqrt{\kappa}-1}{\sqrt{\kappa}+1})^{2k})$. For large $\kappa$, GD requires $O(\kappa \log(1/\epsilon))$ iterations, while NAG requires only $O(\sqrt{\kappa} \log(1/\epsilon))$ iterations.

\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Quadratic Upper Bound]
For an $L$-smooth function, the following holds for any $x, y$:
\begin{align}
    f(y - \alpha \nabla f(y)) \leq f(y) - \alpha \left(1 - \frac{L\alpha}{2}\right) \|\nabla f(y)\|^2
\end{align}
\end{lemma}

\begin{lemma}[Strong Convexity Lower Bound]
For a $\mu$-strongly convex function with minimizer $x^*$, for any $y$:
\begin{align}
    f(x^*) \geq f(y) + \langle \nabla f(y), x^* - y \rangle + \frac{\mu}{2}\|x^* - y\|^2
\end{align}
\end{lemma}

\section*{Main Proof (Step-by-Step Derivation)}
We define an auxiliary sequence $z_k$ to simplify the Lyapunov analysis:
\begin{align}
    z_k = x_k + \frac{1-\beta}{\beta}(x_k - x_{k-1})
\end{align}
Note that $z_{k+1} - x^* = (1+\beta)(x_k - x^*) - \beta(z_k - x^*)$.

\textbf{[Step 1]} Apply the quadratic upper bound (Lemma 1) with step size $\alpha = 1/L$ to the update $x_{k+1} = y_k - \frac{1}{L}\nabla f(y_k)$:
\begin{align}
    f(x_{k+1}) \leq f(y_k) - \frac{1}{2L}\|\nabla f(y_k)\|^2
\end{align}

\textbf{[Step 2]} Apply the strong convexity lower bound (Lemma 2) at point $y_k$ towards $x^*$:
\begin{align}
    f(x^*) \geq f(y_k) + \langle \nabla f(y_k), x^* - y_k \rangle + \frac{\mu}{2}\|y_k - x^*\|^2
\end{align}

\textbf{[Step 3]} Rearrange Lemma 2 to isolate $\langle \nabla f(y_k), y_k - x^* \rangle$:
\begin{align}
    \langle \nabla f(y_k), y_k - x^* \rangle \geq f(y_k) - f(x^*) + \frac{\mu}{2}\|y_k - x^*\|^2
\end{align}

\textbf{[Step 4]} Expand the squared norm $\|z_{k+1} - x^*\|^2$ using the definition $z_{k+1} = y_k + \beta(x_k - z_k)$:
\begin{align}
    \|z_{k+1} - x^*\|^2 = \|y_k - x^* + \beta(x_k - z_k)\|^2
\end{align}

\textbf{[Step 5]} Apply the algebraic identity $\|u+v\|^2 = \|u\|^2 + 2\langle u, v \rangle + \|v\|^2$ with $u = y_k - x^*$ and $v = \beta(x_k - z_k)$:
\begin{align}
    \|z_{k+1} - x^*\|^2 = \|y_k - x^*\|^2 + 2\beta\langle y_k - x^*, x_k - z_k \rangle + \beta^2\|x_k - z_k\|^2
\end{align}

\textbf{[Step 6]} Substitute the identity $x_k - z_k = \frac{1}{1+\beta}(y_k - z_k)$ into the inner product and norm terms:
\begin{align}
    \|z_{k+1} - x^*\|^2 = \|y_k - x^*\|^2 + \frac{2\beta}{1+\beta}\langle y_k - x^*, y_k - z_k \rangle + \frac{\beta^2}{(1+\beta)^2}\|y_k - z_k\|^2
\end{align}

\textbf{[Step 7]} Multiply both sides by $\frac{\mu(1+\beta)^2}{2}$:
\begin{align}
    \frac{\mu(1+\beta)^2}{2}\|z_{k+1} - x^*\|^2 = \frac{\mu(1+\beta)^2}{2}\|y_k - x^*\|^2 + \mu\beta(1+\beta)\langle y_k - x^*, y_k - z_k \rangle + \frac{\mu\beta^2}{2}\|y_k - z_k\|^2
\end{align}

\textbf{[Step 8]} Construct the Lyapunov function difference $V_{k+1} - \beta^2 V_k$. By definition:
\begin{align}
    V_{k+1} - \beta^2 V_k = \left(f(x_{k+1}) - f(x^*)\right) - \beta^2\left(f(x_k) - f(x^*)\right) + \frac{\mu}{2}\|z_{k+1} - x^*\|^2 - \frac{\mu\beta^2}{2}\|z_k - x^*\|^2
\end{align}

\textbf{[Step 9]} Apply the descent bound from [Step 1] to $f(x_{k+1}) - f(x^*)$:
\begin{align}
    f(x_{k+1}) - f(x^*) \leq f(y_k) - f(x^*) - \frac{1}{2L}\|\nabla f(y_k)\|^2
\end{align}

\textbf{[Step 10]} Substitute [Step 9] and [Step 7] into [Step 8]:
\begin{align}
    V_{k+1} - \beta^2 V_k &\leq f(y_k) - f(x^*) - \frac{1}{2L}\|\nabla f(y_k)\|^2 - \beta^2(f(x_k) - f(x^*)) \\
    &\quad + \frac{\mu(1+\beta)^2}{2}\|y_k - x^*\|^2 + \mu\beta(1+\beta)\langle y_k - x^*, y_k - z_k \rangle + \frac{\mu\beta^2}{2}\|y_k - z_k\|^2 - \frac{\mu\beta^2}{2}\|z_k - x^*\|^2
\end{align}

\textbf{[Step 11]} Apply the $L$-smoothness inequality $f(x_k) \leq f(y_k) + \langle \nabla f(y_k), x_k - y_k \rangle + \frac{L}{2}\|x_k - y_k\|^2$ to replace $f(x_k)$:
\begin{align}
    -\beta^2 f(x_k) \leq -\beta^2 f(y_k) - \beta^2 \langle \nabla f(y_k), x_k - y_k \rangle - \frac{L\beta^2}{2}\|x_k - y_k\|^2
\end{align}

\textbf{[Step 12]} Substitute [Step 11] into [Step 10] and combine $f(y_k) - f(x^*)$ terms:
\begin{align}
    V_{k+1} - \beta^2 V_k &\leq (1-\beta^2)(f(y_k) - f(x^*)) - \frac{1}{2L}\|\nabla f(y_k)\|^2 - \beta^2 \langle \nabla f(y_k), x_k - y_k \rangle \\
    &\quad - \frac{L\beta^2}{2}\|x_k - y_k\|^2 + \frac{\mu(1+\beta)^2}{2}\|y_k - x^*\|^2 \\
    &\quad + \mu\beta(1+\beta)\langle y_k - x^*, y_k - z_k \rangle + \frac{\mu\beta^2}{2}\|y_k - z_k\|^2 - \frac{\mu\beta^2}{2}\|z_k - x^*\|^2
\end{align}

\textbf{[Step 13]} Apply strong convexity from [Step 3] to bound $(1-\beta^2)(f(y_k) - f(x^*))$:
\begin{align}
    (1-\beta^2)(f(y_k) - f(x^*)) \leq (1-\beta^2)\langle \nabla f(y_k), y_k - x^* \rangle - \frac{\mu(1-\beta^2)}{2}\|y_k - x^*\|^2
\end{align}

\textbf{[Step 14]} Substitute [Step 13] into [Step 12]. The gradient terms combine:
\begin{align}
    \text{Grad} = (1-\beta^2)\langle \nabla f(y_k), y_k - x^* \rangle - \beta^2 \langle \nabla f(y_k), x_k - y_k \rangle - \frac{1}{2L}\|\nabla f(y_k)\|^2
\end{align}
Using $x_k - y_k = -\beta(x_k - z_k) = \frac{-\beta}{1+\beta}(y_k - z_k)$, we get:
\begin{align}
    \text{Grad} &= \langle \nabla f(y_k), (1-\beta^2)(y_k - x^*) + \frac{\beta^3}{1+\beta}(y_k - z_k) \rangle - \frac{1}{2L}\|\nabla f(y_k)\|^2 \\
    &= \langle \nabla f(y_k), (1-\beta^2)(y_k - x^*) + \beta^2(1-\beta)(y_k - z_k) \rangle - \frac{1}{2L}\|\nabla f(y_k)\|^2
\end{align}

\textbf{[Step 15]} Apply Young's inequality $ab \leq \frac{L}{2}a^2 + \frac{1}{2L}b^2$ to the inner product with $a = \|\nabla f(y_k)\|$ and $b = \|(1-\beta^2)(y_k - x^*) + \beta^2(1-\beta)(y_k - z_k)\|$:
\begin{align}
    \text{Grad} \leq \frac{L}{2}\|(1-\beta^2)(y_k - x^*) + \beta^2(1-\beta)(y_k - z_k)\|^2
\end{align}

\textbf{[Step 16]} Expand the squared norm from [Step 15]:
\begin{align}
    \|\dots\|^2 &= (1-\beta^2)^2\|y_k - x^*\|^2 + 2\beta^2(1-\beta^2)(1-\beta)\langle y_k - x^*, y_k - z_k \rangle \\
    &\quad + \beta^4(1-\beta)^2\|y_k - z_k\|^2
\end{align}

\textbf{[Step 17]} Substitute [Step 15] and [Step 16] back into [Step 14], and combine all terms in $V_{k+1} - \beta^2 V_k$. The coefficients of $\|y_k - x^*\|^2$, $\langle y_k - x^*, y_k - z_k \rangle$, and $\|y_k - z_k\|^2$ must exactly cancel the corresponding terms in [Step 12]. This requires:
\begin{align}
    \frac{\mu(1+\beta)^2}{2} - \frac{\mu(1-\beta^2)}{2} + \frac{L(1-\beta^2)^2}{2} &= \frac{\mu(1+\beta)^2}{2} \\
    \mu\beta(1+\beta) + L\beta^2(1-\beta^2)(1-\beta) &= \mu\beta(1+\beta) \\
    \frac{\mu\beta^2}{2} + \frac{L\beta^4(1-\beta)^2}{2} &= \frac{\mu\beta^2}{2}
\end{align}
These identities hold provided $\beta = \frac{\sqrt{L}-\sqrt{\mu}}{\sqrt{L}+\sqrt{\mu}}$, which satisfies $L(1-\beta)^2 = \mu(1+\beta)^2$.

\textbf{[Step 18]} The remaining terms in $V_{k+1} - \beta^2 V_k$ are:
\begin{align}
    V_{k+1} - \beta^2 V_k \leq -\frac{L\beta^2}{2}\|x_k - y_k\|^2 - \frac{\mu\beta^2}{2}\|z_k - x^*\|^2
\end{align}
Since the right side is non-positive, we conclude $V_{k+1} \leq \beta^2 V_k$.

\section*{Rate Derivation (With Constants)}
From [Step 18], we have established the strictly decreasing Lyapunov property:
\begin{align}
    V_{k+1} \leq \beta^2 V_k
\end{align}
Applying this recursively from $V_0$ yields:
\begin{align}
    V_k \leq \beta^{2k} V_0
\end{align}
By definition, $V_k = f(x_k) - f(x^*) + \frac{\mu}{2}\|z_k - x^*\|^2$. Since $\frac{\mu}{2}\|z_k - x^*\|^2 \geq 0$, it follows that:
\begin{align}
    f(x_k) - f(x^*) \leq V_k \leq \beta^{2k} V_0
\end{align}
Substituting $\beta = \frac{\sqrt{L}-\sqrt{\mu}}{\sqrt{L}+\sqrt{\mu}}$, the convergence rate is precisely:
\begin{align}
    f(x_k) - f(x^*) \leq \left(\frac{\sqrt{L}-\sqrt{\mu}}{\sqrt{L}+\sqrt{\mu}}\right)^{2k} \left( f(x_0) - f(x^*) + \frac{\mu}{2}\|z_0 - x^*\|^2 \right)
\end{align}
To reach an accuracy $\epsilon$, the number of iterations $K$ must satisfy $\left(\frac{\sqrt{\kappa}-1}{\sqrt{\kappa}+1}\right)^{2K} \leq \epsilon$, leading to $K = O\left(\sqrt{\kappa} \log(1/\epsilon)\right)$.

\section*{Special Cases}
\textbf{Case 1: $\mu = 0$ (Convex and Smooth).} When $\mu=0$, $\beta = 1$, and the Lyapunov function changes. The convergence rate degrades to $O(1/k^2)$, which is optimal for convex smooth functions.

\textbf{Case 2: $\mu = L$ ($\kappa = 1$).} When the function is perfectly conditioned, $\beta = 0$. The algorithm reduces to standard Gradient Descent, and the convergence rate becomes $0^{2k} = 0$ for $k \geq 1$, indicating convergence in a single step, consistent with $\alpha = 1/L$.

